"use strict";

// Розділ 4.1.2 — типові кінематичні схеми трансмісії.
//
// Опанасюк, §2.1.2, подає формулу ηм = 0,98^k · 0,97^l · 0,995^m · 0,999^p і
// визначає, що саме рахують: пари циліндричних шестерень, через які на цій
// передачі передається момент; пари конічних (гіпоїдних) шестерень; карданні
// шарніри; шліцьові з'єднання. Таблиці готових значень k, l, m, p джерело не
// подає — їх читають зі схеми, яку студент креслить сам.
//
// Тому кожна схема тут не «взята з таблиці», а ПЕРЕЛІЧЕНА: поряд із числами
// стоїть склад, з якого вони вийшли, і його можна перевірити за власною
// схемою. Це прийняте припущення, а не джерельне значення, і користувач
// лишається вільним виправити будь-яке число.
export function createTransmissionSchemes({dependencies={},loadDependency=null,runtime="browser"}={}) {
  const window=runtime==="browser"?dependencies:undefined; const globalThis=dependencies; const module=loadDependency?{exports:{}}:undefined; const require=loadDependency;

  const SCHEMES = Object.freeze([
    {
      id: "classic-manual",
      label: "Класична: двигун спереду поздовжньо, ведучий міст задній, механічна КП",
      counts: { cylindricalPairs: 2, bevelPairs: 1, cardanJoints: 2, splineJoints: 1 },
      elements: [
        "дві пари циліндричних шестерень КП на проміжній передачі (пара постійного зачеплення і пара вибраної передачі)",
        "одна пара гіпоїдних шестерень головної передачі",
        "два карданні шарніри карданної передачі",
        "одне шліцьове з'єднання карданного вала"
      ]
    },
    {
      id: "front-transverse-manual",
      label: "Передньопривідна: двигун спереду поперечно, механічна КП",
      counts: { cylindricalPairs: 3, bevelPairs: 0, cardanJoints: 2, splineJoints: 1 },
      elements: [
        "дві пари циліндричних шестерень КП на проміжній передачі",
        "одна циліндрична пара головної передачі: за поперечного двигуна вона циліндрична, тому конічних пар немає",
        "два шарніри рівних кутових швидкостей ведучого привода",
        "одне шліцьове з'єднання привода колеса"
      ]
    },
    {
      id: "all-wheel-transfer",
      label: "Повнопривідна: роздавальна коробка, два ведучі мости",
      counts: { cylindricalPairs: 3, bevelPairs: 2, cardanJoints: 4, splineJoints: 2 },
      elements: [
        "дві пари циліндричних шестерень КП і одна пара роздавальної коробки",
        "по одній парі гіпоїдних шестерень на кожен із двох ведучих мостів",
        "чотири карданні шарніри двох карданних передач",
        "два шліцьові з'єднання двох карданних валів"
      ]
    },
    {
      id: "rear-tandem-6x4",
      label: "Вантажна 6×4: механічна КП, міжосьовий дільник і тандем ведучих мостів",
      counts: { cylindricalPairs: 3, bevelPairs: 1, cardanJoints: 4, splineJoints: 2 },
      elements: [
        "дві пари циліндричних шестерень КП на проміжній передачі",
        "одна додаткова зубчаста пара в дільнику потоку тандемного привода",
        "одна гіпоїдна пара на розрахунковому шляху до ведучого моста",
        "чотири карданні шарніри складеного привода заднього візка",
        "два шліцьові з'єднання карданних валів"
      ]
    },
    {
      id: "custom",
      label: "Власна схема — кількості задає користувач",
      counts: null,
      elements: []
    }
  ]);

  function scheme(id) {
    return SCHEMES.find(item => item.id === id) || null;
  }

  // Схема, кількості якої збігаються з уже введеними. Дозволяє показати, що
  // набрані вручну числа відповідають відомій схемі, не нав'язуючи вибору.
  function matchScheme(counts) {
    const found = SCHEMES.find(item => item.counts
      && Object.keys(item.counts).every(key => Number(counts[key]) === item.counts[key]));
    return found ? found.id : "custom";
  }

  // Речення, яким схема пояснює свої числа. Без переліку числа були б такою
  // самою «таблицею нізвідки», яку цей модуль і має заміняти.
  function schemeExplanation(id) {
    const found = scheme(id);
    if (!found || !found.counts) {
      return "Кількості елементів приймає користувач за власною кінематичною схемою.";
    }
    const { cylindricalPairs: k, bevelPairs: l, cardanJoints: m, splineJoints: p } = found.counts;
    return `Прийнято за схемою: k=${k}, l=${l}, m=${m}, p=${p} — `
      + `${found.elements.join("; ")}. Числа випливають зі схеми, а не з таблиці джерела: `
      + "звірте їх із власною кінематичною схемою.";
  }

  return { SCHEMES, scheme, matchScheme, schemeExplanation };
}
